namespace LinqToDB.LINQPad;

/// <summary>
/// Builds connection options for data contexts generated by the dynamic driver.
/// </summary>
/// <remarks>
/// LINQPad 5 enumerates the driver assembly's exported types before the driver can register its assembly
/// resolvers, and on .NET Framework a public <c>DataConnection</c> subclass there forces the exact
/// <c>Microsoft.Bcl.AsyncInterfaces</c> version linq2db references, which the driver never ships. Generated
/// contexts therefore derive from <c>DataConnection</c> directly and get their options from this static helper,
/// whose signature is not resolved during type enumeration.
/// </remarks>
public static class LINQPadContextOptions
{
	/// <summary>
	/// Creates connection options for a generated data context.
	/// </summary>
	/// <param name="providerName">Provider name.</param>
	/// <param name="providerPath">Optional provider assembly path.</param>
	/// <param name="connectionString">Connection string with password manager tokens already replaced.</param>
	/// <returns>Options for the <c>DataConnection</c> base constructor.</returns>
	public static DataOptions Create(string? providerName, string? providerPath, string? connectionString)
	{
		return new DataOptions()
			.UseConnectionString(connectionString ?? throw new LinqToDBLinqPadException("Connection string missing"))
			.UseDataProvider(DatabaseProviders.GetDataProvider(providerName, connectionString, providerPath));
	}
}
